arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ a: __type(name: \"Query\") { fields { name args { name type { kind name ofType { kind name ofType { kind name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['a']['fields']:
    if f['name'] in ('cycles','projects','issues','users'):
        for a in f['args']:
            if a['name']=='filter':
                t=a['type']
                chain=[]
                while t:
                    chain.append(t.get('name') or t.get('kind'))
                    t=t.get('ofType')
                print(f['name'], 'filter:', '<'.join(chain))
"

